WITH remaining_keys AS (SELECT country FROM sessions EXCEPT ALL SELECT country FROM sessions WHERE customer_id IN (5, 18, 24, 29)), kept_rows AS (SELECT s.* FROM sessions s INNER JOIN remaining_keys k ON s.country = k.country) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, MIN(started_at) AS started_at, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT country) AS distinct_countries FROM kept_rows GROUP BY quarter_start;
